entries[451936] = { ["name"] = "Grimweave Orb", ["text"] = "100 yd range\nChanneled (10 sec cast)\nUnleashes an orb of rapidly weaving web in front of the caster's location that inflicts 8 Nature damage and an additional 2 Nature every 1 sec to enemies within 4 yards of the orb and reduces their movement speed by 30 % for 3 sec." }
